public class Solution extends VersionControl {
    public int firstBadVersion(int n) {
        int left = 1, right = n;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (isBadVersion(mid)) {
                if (mid == 1 || !isBadVersion(mid - 1)) {
                    return mid; // 找到第一个坏版本
                }
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }
}
